const EXAMPLE_LIBRARY=[{"name":"bilibili_fans","title":"Bilibili Fans","desc":"Displays the follower count of a Bilibili account","source":"# @name    Bilibili Fans\n# @desc    Displays the follower count of a Bilibili account\n# @author  Anthonyrr98\n# @version 1.0\n# @config  uid    text   \"Bilibili UID\" default=\"\" help=\"The numeric UID from the space page\"\n# @config  every  number \"Refresh\"      default=10 min=1 max=60 unit=min\n# @config  accent color  \"Accent\"       default=#FB7299\n\nclass BilibiliFans\n  var url, period, ticks, in_flight\n  var fans, label, color\n\n  def init()\n    var uid = store.get(\"uid\")\n    self.url = uid == \"\" ? nil : \"https://api.bilibili.com/x/relation/stat?vmid=\" + uid\n    self.period = store.get(\"every\") * 60\n    self.ticks = 0\n    self.in_flight = false\n    self.fans = store.get(\"fans\")\n    self.label = self.url == nil ? \"UID?\" : (self.fans == nil ? \"...\" : str(self.fans))\n    self.color = store.get(\"accent\")\n    if self.color == nil self.color = settings.get(\"textColor\") end\n  end\n\n  def on_body(body, status)\n    self.in_flight = false\n    if body == nil || status != 200\n      if self.fans == nil self.label = \"NET\" end\n      return\n    end\n    var m = re.search(\"\\\"follower\\\":([0-9]+)\", body)\n    if m == nil\n      if self.fans == nil self.label = \"API\" end\n      return\n    end\n    var value = int(m[1])\n    self.fans = value\n    self.label = str(value)\n    store.set(\"fans\", value)\n  end\n\n  def loop()\n    if self.url == nil return end\n    if self.ticks <= 0\n      self.ticks = self.period\n      if !self.in_flight\n        self.in_flight = true\n        http.get(self.url, / b, st -> self.on_body(b, st),\n                 {'find': \"\\\"follower\\\":\", 'keep': 48})\n      end\n    end\n    self.ticks -= 1\n  end\n\n  def draw()\n    clear()\n    line(1, 0, 3, 2, self.color)\n    line(6, 0, 4, 2, self.color)\n    rect(0, 2, 8, 6, self.color)\n    pixel(2, 4, self.color)\n    pixel(5, 4, self.color)\n    line(3, 6, 4, 6, self.color)\n    scroll_text(9, 6, width() - 9, self.label, self.color)\n  end\n\n  def on_button(btn)\n    if btn == \"select\" self.ticks = 0 end\n  end\nend\n\nreturn BilibiliFans()\n"},{"name":"binary_clock","title":"Binary Clock","desc":"Six-digit binary clock","source":"# @name Binary Clock\n# @desc Six-digit binary clock\n# @author Anthonyrr98\n# @version 1.0\n# @config on color \"Lit colour\" default=#00AAFF\n# @config off color \"Unlit colour\" default=#101820\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass BinaryClockApp\n  var lit, dim, dwell, vals\n  def init()\n    self.lit = store.get(\"on\")\n    self.dim = store.get(\"off\")\n    self.dwell = store.get(\"show\") * 1000\n    self.vals = [0, 0, 0, 0, 0, 0]\n  end\n  def loop()\n    self.vals[0] = hour() / 10\n    self.vals[1] = hour() % 10\n    self.vals[2] = minute() / 10\n    self.vals[3] = minute() % 10\n    self.vals[4] = second() / 10\n    self.vals[5] = second() % 10\n  end\n  def draw()\n    clear()\n    for i : 0 .. 5\n      for b : 0 .. 3\n        var c = ((self.vals[i] / (1 << b)) % 2) == 1 ? self.lit : self.dim\n        rect_fill(1 + i * 5, 6 - b * 2, 2, 2, c)\n      end\n    end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn BinaryClockApp()\n"},{"name":"color_waves","title":"Color Waves","desc":"Flowing rainbow colour waves","source":"# @name Color Waves\n# @desc Flowing rainbow colour waves\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=80 min=10 max=300 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass ColorWavesApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0, \"palette\": \"Rainbow\"}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"ColorWaves\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn ColorWavesApp()\n"},{"name":"dice","title":"Dice","desc":"Press select to roll a pixel die","source":"# @name Dice\n# @desc Press select to roll a pixel die\n# @author Anthonyrr98\n# @version 1.0\n# @config face color \"Face colour\" default=#E8E8E8\n# @config pip color \"Pip colour\" default=#202020\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nimport math\n\nclass DiceApp\n  var value, face, pip, dwell\n  def init()\n    self.value = 1 + math.rand() % 6\n    self.face = store.get(\"face\")\n    self.pip = store.get(\"pip\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    clear()\n    rect_fill(12, 0, 8, 8, self.face)\n    if self.value == 1 || self.value == 3 || self.value == 5\n      pixel(15, 3, self.pip)\n      pixel(16, 4, self.pip)\n    end\n    if self.value >= 2\n      pixel(13, 1, self.pip)\n      pixel(14, 2, self.pip)\n      pixel(18, 5, self.pip)\n      pixel(19, 6, self.pip)\n    end\n    if self.value >= 4\n      pixel(18, 1, self.pip)\n      pixel(19, 2, self.pip)\n      pixel(13, 5, self.pip)\n      pixel(14, 6, self.pip)\n    end\n    if self.value == 6\n      pixel(13, 3, self.pip)\n      pixel(14, 4, self.pip)\n      pixel(18, 3, self.pip)\n      pixel(19, 4, self.pip)\n    end\n  end\n  def on_button(btn)\n    if btn == \"select\" self.value = 1 + math.rand() % 6 end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn DiceApp()\n"},{"name":"fireworks","title":"Fireworks","desc":"Colourful pixel fireworks","source":"# @name Fireworks\n# @desc Colourful pixel fireworks\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=100 min=25 max=300 step=5 unit=%\n# @config density slider \"Burst density\" default=70 min=10 max=100 step=5 unit=%\n# @config intensity slider \"Brightness\" default=100 min=10 max=100 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass FireworksApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0,\n               \"density\": store.get(\"density\"), \"intensity\": store.get(\"intensity\")}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"Fireworks\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn FireworksApp()\n"},{"name":"game_of_life","title":"Game of Life","desc":"Conway cellular automaton","source":"# @name Game of Life\n# @desc Conway cellular automaton\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=5 min=1 max=20 step=1 unit=fps\n# @config density slider \"Start density\" default=32 min=10 max=70 step=1 unit=%\n# @config alive color \"Cell colour\" default=#00FF66\n# @config show number \"Duration\" default=15 min=3 max=120 unit=s\n\nimport math\n\nclass GameOfLifeApp\n  var cells, next, interval, last_step, alive, dwell\n  def init()\n    self.cells = []\n    self.next = []\n    for i : 0 .. width() * height() - 1\n      self.cells.push((math.rand() % 100) < store.get(\"density\") ? 1 : 0)\n      self.next.push(0)\n    end\n    self.interval = 1000 / store.get(\"speed\")\n    self.last_step = now_ms()\n    self.alive = store.get(\"alive\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    clear()\n    var w = width()\n    var h = height()\n    if now_ms() - self.last_step >= self.interval\n      self.last_step = now_ms()\n      for y : 0 .. h - 1\n        for x : 0 .. w - 1\n          var n = 0\n          for dy : -1 .. 1\n            for dx : -1 .. 1\n              if dx != 0 || dy != 0\n                n += self.cells[((y + dy + h) % h) * w + ((x + dx + w) % w)]\n              end\n            end\n          end\n          var here = self.cells[y * w + x]\n          self.next[y * w + x] = (n == 3 || (here == 1 && n == 2)) ? 1 : 0\n        end\n      end\n      var swap = self.cells\n      self.cells = self.next\n      self.next = swap\n    end\n    for i : 0 .. w * h - 1\n      if self.cells[i] == 1 pixel(i % w, i / w, self.alive) end\n    end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn GameOfLifeApp()\n"},{"name":"light_chart","title":"Light Chart","desc":"Rolling ambient-light history","source":"# @name Light Chart\n# @desc Rolling ambient-light history\n# @author Anthonyrr98\n# @version 1.0\n# @config every number \"Sample interval\" default=1 min=1 max=60 unit=min\n# @config trend color \"Trend colour\" default=#FFAA00\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass LightChartApp\n  var samples, ticks, period, current, trend, dwell\n  def init()\n    self.samples = []\n    self.ticks = 0\n    self.period = store.get(\"every\") * 60\n    self.current = 0\n    self.trend = store.get(\"trend\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def loop()\n    if self.ticks <= 0\n      self.ticks = self.period\n      var value = sensor.light()\n      if value != nil\n        self.current = value\n        self.samples.push(value)\n        if size(self.samples) > 16 self.samples.remove(0) end\n      end\n    end\n    self.ticks -= 1\n  end\n  def draw()\n    clear()\n    if size(self.samples) > 1\n      line_chart(self.samples, self.trend, true)\n    else\n      progress(self.current, self.trend, 0x101010)\n    end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn LightChartApp()\n"},{"name":"looking_eyes","title":"Looking Eyes","desc":"Animated eyes watching the room","source":"# @name Looking Eyes\n# @desc Animated eyes watching the room\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=100 min=25 max=300 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass LookingEyesApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"LookingEyes\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn LookingEyesApp()\n"},{"name":"matrix_rain","title":"Matrix Rain","desc":"Falling digital rain with configurable trails","source":"# @name    Matrix Rain\n# @desc    Falling digital rain with configurable trails\n# @author  Anthonyrr98\n# @version 1.1\n# @config  speed slider \"Speed\"        default=100 min=25 max=300 step=5 unit=%\n# @config  trail slider \"Trail length\" default=7 min=3 max=12 step=1 unit=px\n# @config  hue   slider \"Colour hue\"   default=120 min=0 max=360 step=5\n# @config  show  number \"Duration\"     default=15 min=3 max=120 unit=s\n\nimport math\n\nclass MatrixRain\n  var heads, interval, last_step\n  var trail, hue, dwell\n\n  def init()\n    self.heads = []\n    for x : 0 .. width() - 1\n      self.heads.push(-(math.rand() % (height() + 8)))\n    end\n    self.interval = 10000 / store.get(\"speed\")\n    self.last_step = now_ms()\n    self.trail = store.get(\"trail\")\n    self.hue = store.get(\"hue\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n\n  def draw()\n    clear()\n    var now = now_ms()\n    if now - self.last_step >= self.interval\n      self.last_step = now\n      for x : 0 .. width() - 1\n        self.heads[x] += 1\n        if self.heads[x] - self.trail >= height()\n          self.heads[x] = -(math.rand() % (height() + 8))\n        end\n      end\n    end\n\n    for x : 0 .. width() - 1\n      for t : 0 .. self.trail - 1\n        var y = self.heads[x] - t\n        if y >= 0 && y < height()\n          if t == 0\n            pixel(x, y, hsv(self.hue, 25, 100))\n          else\n            var value = 72 - (t * 64 / self.trail)\n            if value < 8 value = 8 end\n            pixel(x, y, hsv(self.hue, 100, value))\n          end\n        end\n      end\n    end\n  end\n\n  def duration()\n    return self.dwell\n  end\nend\n\nreturn MatrixRain()\n"},{"name":"moon_phase","title":"Moon Phase","desc":"Approximate current lunar phase","source":"# @name Moon Phase\n# @desc Approximate current lunar phase\n# @author Anthonyrr98\n# @version 1.0\n# @config moon color \"Moon colour\" default=#FFF0A0\n# @config dim color \"New moon colour\" default=#202018\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass MoonPhaseApp\n  var phase, moon, dim, dwell\n  def init()\n    self.phase = 0\n    self.moon = store.get(\"moon\")\n    self.dim = store.get(\"dim\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def loop()\n    var e = epoch_ms()\n    if e >= 0\n      var days = e / 86400000.0 - 10962.0\n      var cycle = days - int(days / 29.530588) * 29.530588\n      self.phase = int(cycle * 8 / 29.530588)\n    end\n  end\n  def draw()\n    clear()\n    if self.phase == 0\n      circle(15, 3, 3, self.dim)\n    elif self.phase == 4\n      circle_fill(15, 3, 3, self.moon)\n    elif self.phase == 1\n      circle_fill(15, 3, 3, self.moon)\n      circle_fill(14, 3, 3, 0x000000)\n    elif self.phase == 2\n      circle_fill(15, 3, 3, self.moon)\n      rect_fill(12, 0, 3, 7, 0x000000)\n    elif self.phase == 3\n      circle_fill(15, 3, 3, self.moon)\n      circle_fill(12, 3, 3, 0x000000)\n    elif self.phase == 5\n      circle_fill(15, 3, 3, self.moon)\n      circle_fill(18, 3, 3, 0x000000)\n    elif self.phase == 6\n      circle_fill(15, 3, 3, self.moon)\n      rect_fill(16, 0, 3, 7, 0x000000)\n    else\n      circle_fill(15, 3, 3, self.moon)\n      circle_fill(17, 3, 3, 0x000000)\n    end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn MoonPhaseApp()\n"},{"name":"pacifica","title":"Pacifica","desc":"Calm animated ocean waves","source":"# @name Pacifica\n# @desc Calm animated ocean waves\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=70 min=10 max=200 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass PacificaApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"Pacifica\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn PacificaApp()\n"},{"name":"plasma_clock","title":"Plasma Clock","desc":"Clock over an animated plasma cloud","source":"# @name Plasma Clock\n# @desc Clock over an animated plasma cloud\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Background speed\" default=35 min=5 max=150 step=5 unit=%\n# @config tint color \"Text colour\" default=#FFFFFF\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass PlasmaClockApp\n  var fx, label, tint, dwell, last_second\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0, \"palette\": \"Ocean\"}\n    self.label = \"--:--\"\n    self.tint = store.get(\"tint\")\n    self.dwell = store.get(\"show\") * 1000\n    self.last_second = -1\n  end\n  def loop()\n    var s = second()\n    if s != self.last_second\n      self.last_second = s\n      var m = minute()\n      self.label = str(hour()) + \":\" + (m < 10 ? \"0\" + str(m) : str(m))\n    end\n  end\n  def draw()\n    effect(\"PlasmaCloud\", self.fx)\n    text((width() - text_ink_width(self.label)) / 2, 6, self.label, self.tint)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn PlasmaClockApp()\n"},{"name":"pomodoro","title":"Pomodoro","desc":"A select-button focus timer","source":"# @name Pomodoro\n# @desc A select-button focus timer\n# @author Anthonyrr98\n# @version 1.0\n# @config minutes number \"Focus time\" default=25 min=1 max=120 unit=min\n# @config active color \"Active colour\" default=#FF4040\n# @config paused color \"Paused colour\" default=#FFAA00\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass PomodoroApp\n  var left, total, running, label, active, paused, dwell\n  def init()\n    self.total = store.get(\"minutes\") * 60\n    self.left = self.total\n    self.running = false\n    self.label = str(store.get(\"minutes\")) + \"m\"\n    self.active = store.get(\"active\")\n    self.paused = store.get(\"paused\")\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def loop()\n    if self.running && self.left > 0\n      self.left -= 1\n      var mins = (self.left + 59) / 60\n      self.label = str(mins) + \"m\"\n      if self.left == 0\n        self.running = false\n        self.label = \"DONE\"\n        notify({\"text\": \"Pomodoro finished\", \"textColor\": self.active})\n      end\n    end\n  end\n  def draw()\n    clear()\n    var c = self.running ? self.active : self.paused\n    text((width() - text_ink_width(self.label)) / 2, 6, self.label, c)\n    progress(self.left * 100 / self.total, c, 0x101010)\n  end\n  def on_button(btn)\n    if btn == \"select\"\n      if self.left == 0\n        self.left = self.total\n        self.label = str(self.total / 60) + \"m\"\n      end\n      self.running = !self.running\n    end\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn PomodoroApp()\n"},{"name":"radar","title":"Radar","desc":"Rotating green radar sweep","source":"# @name Radar\n# @desc Rotating green radar sweep\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=100 min=25 max=300 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass RadarApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"Radar\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn RadarApp()\n"},{"name":"snake_visual","title":"Neon Snake","desc":"Animated neon snake effect","source":"# @name Neon Snake\n# @desc Animated neon snake effect\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=100 min=25 max=300 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass NeonSnakeApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0, \"palette\": \"Rainbow\"}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"Snake\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn NeonSnakeApp()\n"},{"name":"twinkling_stars","title":"Twinkling Stars","desc":"A field of softly twinkling stars","source":"# @name Twinkling Stars\n# @desc A field of softly twinkling stars\n# @author Anthonyrr98\n# @version 1.0\n# @config speed slider \"Speed\" default=70 min=10 max=200 step=5 unit=%\n# @config density slider \"Star density\" default=60 min=5 max=100 step=5 unit=%\n# @config intensity slider \"Brightness\" default=100 min=10 max=100 step=5 unit=%\n# @config show number \"Duration\" default=12 min=3 max=120 unit=s\n\nclass TwinklingStarsApp\n  var fx, dwell\n  def init()\n    self.fx = {\"speed\": store.get(\"speed\") / 100.0,\n               \"density\": store.get(\"density\"), \"intensity\": store.get(\"intensity\")}\n    self.dwell = store.get(\"show\") * 1000\n  end\n  def draw()\n    effect(\"TwinklingStars\", self.fx)\n  end\n  def duration()\n    return self.dwell\n  end\nend\nreturn TwinklingStarsApp()\n"}];
