    const q=w?w.text.toLowerCase():'';
    acItems=BERRY_API.concat(BERRY_MODS,BERRY_CORE).filter(s=>s.toLowerCase().startsWith(q)).slice(0,40);
    if(!acItems.length||(w&&acItems.length===1&&acItems[0].split('(')[0]===w.text))return acClose();
    acSel=0;acPaint();
